<script lang="ts">
 import { terminalPalettes,type CursorShape } from './themes'
 let {palette,fontSize,cursor,onpalette,onfont,oncursor}:{palette:string;fontSize:number;cursor:CursorShape;onpalette:(id:string)=>void;onfont:(delta:number)=>void;oncursor:(shape:CursorShape)=>void}=$props()
</script>
<section aria-label="Terminal appearance" class="appearance">
 <div><p class="eyebrow">Make room for focus</p><h3>Colour theme</h3><p class="hint">A palette for your terminal, independent of the app’s appearance.</p></div>
 <div class="palettes" role="group" aria-label="Terminal themes">
  {#each terminalPalettes as item}<button class="palette" class:chosen={palette===item.id} aria-pressed={palette===item.id} aria-label={`Use ${item.name} theme`} onclick={()=>onpalette(item.id)}>
   <span class="preview" style={`background:${item.colors.background};color:${item.colors.foreground}`}><span style={`color:${item.colors.green}`}>~/workspace</span><span>$ reet agent status<span class="sample-cursor" style={`background:${item.colors.cursor}`}></span></span><span class="dots">{#each [item.colors.red,item.colors.yellow,item.colors.green,item.colors.blue,item.colors.magenta] as color}<i style={`background:${color}`}></i>{/each}</span></span>
   <strong>{item.name}<span aria-hidden="true">{palette===item.id?'✓':''}</span></strong><small>{item.detail}</small>
  </button>{/each}
 </div>
 <button class="follow-app" aria-pressed={palette==='system'} onclick={()=>onpalette('system')}>Follow app appearance <span>{palette==='system'?'✓':'↗'}</span></button>
 <div class="setting"><div><h3>Text size</h3><p class="hint">A comfortable size for this browser.</p></div><div class="font-control"><button aria-label="Decrease terminal font" disabled={fontSize<=10} onclick={()=>onfont(-1)}>A−</button><span aria-label="Terminal font size">{fontSize}</span><button aria-label="Increase terminal font" disabled={fontSize>=22} onclick={()=>onfont(1)}>A+</button></div></div>
 <label class="cursor-setting">Cursor<select aria-label="Terminal cursor style" value={cursor} onchange={e=>oncursor(e.currentTarget.value as CursorShape)}><option value="bar">Bar</option><option value="block">Block</option><option value="underline">Underline</option></select></label>
 <p class="hint footnote">Themes set the default text and terminal palette. Programs choose which text is coloured; plain output stays plain. In <code>top</code>, press <kbd>z</kbd> to toggle its colour display. Saved in this browser; your shell keeps running.</p>
</section>
